698	+    public async Task<SitzplanDto?> GetSitzplanAsync(string veranstaltungId)
699	+    {
700	+        var veranstaltung = await db.Veranstaltungen
701	+            .Include(v => v.Raum)
702	+            .FirstOrDefaultAsync(v => v.Id == veranstaltungId);
703	+
704	+        if (veranstaltung is null)
705	+        {
706	+            return null;
707	+        }
708	+
709	+        var raum = veranstaltung.Raum!;
710	+
711	+        var belegteCodes = (await db.Sitzplatzbelegungen
712	+            .Where(s => s.VeranstaltungId == veranstaltungId)
713	+            .Select(s => s.SitzplatzCode)
714	+            .ToListAsync())
715	+            .ToHashSet();
716	+
717	+        var reihen = raum.Reihen.Select(reihe =>
718	+        {
719	+            var positionen = new List<SitzplanPositionDto>();
720	+            for (var spalte = 1; spalte <= raum.Spalten; spalte++)
721	+            {
722	+                if (raum.GangSpalten.Contains(spalte))
723	+                {
724	+                    positionen.Add(new SitzplanPositionDto(spalte, "Gang", null, null));
725	+                }
726	+                else
727	+                {
728	+                    var code = $"{reihe}{spalte}";
729	+                    positionen.Add(new SitzplanPositionDto(spalte, "Sitzplatz", code, belegteCodes.Contains(code) ? "Belegt" : "Frei"));
730	+                }
731	+            }
732	+
733	+            return new SitzplanReiheDto(reihe, positionen);
734	+        }).ToList();
735	+
736	+        return new SitzplanDto(veranstaltung.Id, raum.Id, raum.Name, reihen);
737	+    }
738	 }
